using NovaHarvest.Core.Player; using NovaHarvest.Core.World; namespace NovaHarvest.Core.Systems; public sealed class BuildingSystem { readonly PlayerController _player; readonly Inventory _inventory; readonly WorldManager _world; int _nextFarmPlotId=1; public BuildingSystem(PlayerController p,Inventory i,WorldManager w){_player=p;_inventory=i;_world=w;_nextFarmPlotId=w.GetByType(WorldObjectType.FarmPlot).Count+1;} public bool BuildFarmPlot(int x,int y){if(!_inventory.Has("farm_plot")||_world.HasObjectAt(x,y))return false;var plot=new FarmPlotObject($"farm_plot_{_nextFarmPlotId}",x,y,_nextFarmPlotId);if(!_world.Add(plot))return false;_inventory.Remove("farm_plot");_nextFarmPlotId++;return true;} public bool BuildFarmPlotNearPlayer()=>BuildFarmPlot(_player.Position.X+1,_player.Position.Y); }
